// Auto-generated for the Unit Board — AWL Sublist 8
window.A8_DASHBOARD_UNITS = [{"unit":1,"theme":"abandon – bias","cards":[{"w":"abandon","p":"v.","d":"to leave something forever","c":"放棄","s":"They had to abandon their home due to the natural disaster.","t":"由於自然災害，他們不得不放棄他們的家。"},{"w":"abandoned","p":"adj.","d":"left empty or alone forever","c":"被遺棄的","s":"The abandoned building became a refuge for stray animals.","t":"被遺棄的建築成了流浪動物的避難所。"},{"w":"company","p":"n.","d":"a business","c":"公司","s":"He works for a company that specializes in renewable energy.","t":"他在一家專門從事可再生能源的公司工作。"},{"w":"company","p":"n.","d":"being with someone so they are not alone","c":"陪伴","s":"She appreciated the company of her friends during tough times.","t":"在困難時期，她感激朋友的陪伴。"},{"w":"accompany","p":"v.","d":"to go somewhere with someone","c":"陪伴","s":"He offered to accompany her to the doctor's appointment.","t":"他提議陪她去看醫生。"},{"w":"accompanied","p":"adj.","d":"having something come with it","c":"陪同的","s":"The offer was accompanied by a promise of support.","t":"這個提議伴隨著支援的承諾。"},{"w":"keep someone company","p":"phr.","d":"to stay with someone so they are not alone","c":"陪伴某人","s":"She decided to keep someone company her friend who was feeling down.","t":"她決定陪伴感覺沮喪的朋友。"},{"w":"companion","p":"n.","d":"a person you spend time with","c":"伴侶","s":"His dog has been a loyal companion for many years.","t":"多年來，他的狗一直是忠實的伴侶。"},{"w":"accumulate","p":"v.","d":"to collect more and more over time","c":"累積","s":"Over time, he managed to accumulate a significant amount of rare stamps in his collection.","t":"隨著時間的推移，他在他的收藏中累積了大量的珍稀郵票。"},{"w":"accumulated","p":"adj.","d":"collected over a period of time","c":"累積的","s":"The accumulated knowledge from years of study prepared him well for the project.","t":"多年學習的累積知識為他的項目做好了充分準備。"},{"w":"accumulation","p":"n.","d":"an amount that has collected over time","c":"累積","s":"The accumulation of plastic in the oceans is a serious environmental issue.","t":"塑料在海洋中的累積是一個嚴重的環境問題。"},{"w":"ambiguous","p":"adj.","d":"not clear; having more than one meaning","c":"模稜兩可的","s":"The instructions were ambiguous and caused a lot of confusion among the team.","t":"指示不明確，使團隊中的很多人感到困惑。"},{"w":"appendix","p":"n.","d":"extra information at the end of a book","c":"附錄","s":"The book includes an appendix with additional resources for further reading.","t":"這本書包括一個附錄，其中有進一步閱讀的額外資源。"},{"w":"appreciate","p":"v.","d":"to be thankful for something","c":"感激","s":"I appreciate your help during this difficult time.","t":"我感激你在這困難時期的幫助。"},{"w":"appreciate","p":"v.","d":"to see how good or beautiful something is","c":"欣賞","s":"She could appreciate the beauty of the artwork.","t":"她可以欣賞這件藝術品的美。"},{"w":"appreciation","p":"n.","d":"the feeling of being thankful","c":"感激","s":"His appreciation for the support from his family was evident.","t":"他對家人支持的感激之情顯而易見。"},{"w":"appreciation","p":"n.","d":"understanding how good or beautiful something is","c":"欣賞","s":"An appreciation of classical music can enhance one's cultural understanding.","t":"對古典音樂的欣賞可以增強一個人的文化理解。"},{"w":"arbitrary","p":"adj.","d":"chosen by chance, not by reason","c":"任意的","s":"The decision seemed arbitrary and lacked a solid basis.","t":"這個決定似乎是任意的，缺乏堅實的依據。"},{"w":"automatic","p":"adj.","d":"working by itself","c":"自動的","s":"The automatic doors opened as we approached the building.","t":"當我們走近大廈時，自動門打開了。"},{"w":"automatically","p":"adv.","d":"by itself, without a person","c":"自動地","s":"The system automatically updates to ensure optimal performance.","t":"系統自動更新以確保最佳性能。"},{"w":"bias","p":"n.","d":"an unfair opinion for or against something","c":"偏見","s":"It's important to recognize and address any bias in the study.","t":"重要的是認識並解決研究中的任何偏見。"}]},{"unit":2,"theme":"biased – currency","cards":[{"w":"biased","p":"adj.","d":"unfairly favoring one side","c":"有偏見的","s":"The review was clearly biased, lacking objectivity.","t":"這個評論顯然是有偏見的，缺乏客觀性。"},{"w":"chart","p":"n.","d":"a picture that shows information","c":"圖表","s":"The chart displayed the sales figures for the past year.","t":"圖表顯示了過去一年的銷售數字。"},{"w":"chart","p":"v.","d":"to record something step by step","c":"繪製圖表","s":"They needed to chart the progress of the project carefully.","t":"他們需要仔細繪製項目進展的圖表。"},{"w":"uncharted territory","p":"phr.","d":"a new area nobody knows about","c":"未知領域","s":"Venturing into uncharted territory, the team faced many unforeseen challenges.","t":"冒險進入未知領域，團隊面臨許多未預見的挑戰。"},{"w":"clear","p":"adj.","d":"easy to understand","c":"清楚的","s":"The instructions should be clear and easy to follow.","t":"指示應該清楚且易於遵循。"},{"w":"clarify","p":"v.","d":"to make something clearer","c":"澄清","s":"Can you clarify the objectives of the assignment?","t":"你能澄清一下任務的目標嗎？"},{"w":"clarity","p":"n.","d":"the quality of being clear","c":"清晰度","s":"He explained the concept with great clarity, making it easy to understand.","t":"他非常清楚地解釋了這個概念，使其容易理解。"},{"w":"conform to","p":"phr.","d":"to follow a rule or standard","c":"符合","s":"All products must conform to the safety standards before they are sold.","t":"所有產品在出售前都必須符合安全標準。"},{"w":"conformity","p":"n.","d":"behaving the same as other people","c":"符合","s":"There's a culture of conformity in the corporate world that often stifles creativity.","t":"企業界存在一種常常抑制創造力的符合文化。"},{"w":"commodity","p":"n.","d":"a product that is bought and sold","c":"商品","s":"The price of the commodity fluctuated in the international market.","t":"商品在國際市場上的價格波動。"},{"w":"complement","p":"adj.","d":"going well together","c":"互補的","s":"The two technologies are a complement to each other, enhancing the system's efficiency.","t":"這兩種技術相互補充，提高了系統的效率。"},{"w":"complement","p":"v.","d":"to go well with something","c":"補充","s":"The wine will complement the flavors of the meal perfectly.","t":"酒將完美補充飯菜的味道。"},{"w":"contemporary","p":"adj.","d":"modern; of the present time","c":"當代的","s":"The museum featured contemporary artists from around the world.","t":"博物館展出了來自世界各地的當代藝術家。"},{"w":"contradict","p":"v.","d":"to say the opposite of something","c":"矛盾","s":"His statement seemed to contradict the evidence presented in the case.","t":"他的陳述似乎與案件中呈現的證據矛盾。"},{"w":"contradictory","p":"adj.","d":"saying opposite things","c":"矛盾的","s":"The contradictory information made it difficult to arrive at a conclusion.","t":"矛盾的信息使得得出結論變得困難。"},{"w":"contradiction","p":"n.","d":"a difference between two facts","c":"矛盾","s":"The theory was full of contradiction and unclear assumptions.","t":"這個理論充滿了矛盾和不清楚的假設。"},{"w":"crucial","p":"adj.","d":"extremely important","c":"關鍵的","s":"Making accurate forecasts is crucial for the success of the project.","t":"做出準確的預測對於項目的成功至關重要。"},{"w":"current","p":"adj.","d":"happening now","c":"現在的","s":"The current situation requires immediate attention.","t":"當前的情況需要立即關注。"},{"w":"current","p":"n.","d":"a flow of electricity","c":"電流","s":"The device measures the current flowing through the circuit.","t":"該設備測量通過電路的電流。"},{"w":"current","p":"n.","d":"a flow of water in the sea or a river","c":"水流/洋流","s":"The boat was carried away by the strong current.","t":"船被強大的水流/洋流帶走了。"},{"w":"currency","p":"n.","d":"the money used in a country","c":"貨幣","s":"The exchange rate between the two currency fluctuates daily.","t":"這兩種貨幣的匯率每天都在波動。"}]},{"unit":3,"theme":"denote – exploited","cards":[{"w":"denote","p":"v.","d":"to mean or stand for something","c":"表示","s":"The red symbol on the map denote a place of interest.","t":"地圖上的紅色符號表示一個有趣的地方。"},{"w":"detect","p":"v.","d":"to find or discover something","c":"檢測","s":"The system can detect any unauthorized access.","t":"系統可以檢測到任何未經授權的訪問。"},{"w":"detected","p":"adj.","d":"found or discovered","c":"檢測到的","s":"A detected leak in the pipeline prompted immediate repair.","t":"在管道中檢測到泄漏，立即進行了修理。"},{"w":"detective","p":"n.","d":"a person who solves crimes","c":"偵探","s":"The detective was hired to solve the mysterious case.","t":"偵探被聘來解決神秘的案件。"},{"w":"detection","p":"n.","d":"the act of finding something","c":"檢測","s":"Early detection of the disease greatly increases the chances of successful treatment.","t":"早期檢測疾病大大增加了成功治療的機會。"},{"w":"deviate from","p":"phr.","d":"to move away from the usual way","c":"偏離","s":"It's important not to deviate from the topic during the discussion.","t":"在討論中不偏離主題很重要。"},{"w":"deviation","p":"n.","d":"a difference from the usual way","c":"偏差","s":"The deviation from the norm was considered significant.","t":"被認為是重大的偏離常規。"},{"w":"displace","p":"v.","d":"to force people to leave their homes; to replace","c":"取代","s":"The new technology might displace manual labor in some industries.","t":"新技術可能會在一些行業中取代人工。"},{"w":"displaced","p":"adj.","d":"forced to leave a home or job","c":"被取代的","s":"The displaced workers struggled to find new jobs.","t":"被取代的工人努力尋找新工作。"},{"w":"displacement","p":"n.","d":"moving something from its usual place","c":"取代","s":"The displacement of traditional methods can lead to increased efficiency.","t":"取代傳統方法可能會提高效率。"},{"w":"drama","p":"n.","d":"a play or show","c":"戲劇","s":"The drama tells a story of love and betrayal.","t":"戲劇講述了一個關於愛與背叛的故事。"},{"w":"dramatic","p":"adj.","d":"exciting or sudden","c":"戲劇性的","s":"The dramatic change in weather conditions affected their plans.","t":"戲劇性的天氣變化影響了他們的計劃。"},{"w":"dramatically","p":"adv.","d":"in a very large or sudden way","c":"戲劇性地","s":"Sales have increased dramatically since the new marketing campaign was launched.","t":"自新的營銷活動推出以來，銷售額戲劇性地增加了。"},{"w":"event","p":"n.","d":"something that happens, especially something important","c":"事件","s":"The unexpected event caused a delay in the schedule.","t":"意外事件導致時間表延誤。"},{"w":"eventually","p":"adv.","d":"in the end","c":"最終","s":"After facing many challenges, they eventually achieved their goal.","t":"在面對許多挑戰後，他們最終實現了他們的目標。"},{"w":"exhibit","p":"v.","d":"to show something to the public","c":"展示","s":"The museum will exhibit new artifacts next month.","t":"博物館將在下個月展示新的文物。"},{"w":"exhibit","p":"n.","d":"an object shown in a museum","c":"展品","s":"The exhibit attracted a lot of attention from visitors.","t":"展品吸引了很多遊客的關注。"},{"w":"exhibition","p":"n.","d":"a public show of art or objects","c":"展覽","s":"The annual art exhibition showcases works from local artists.","t":"年度藝術展覽展示了當地藝術家的作品。"},{"w":"on exhibit","p":"phr.","d":"being shown to the public","c":"在展","s":"The rare paintings will be on exhibit for a limited time.","t":"珍稀的畫作將在有限的時間內展出。"},{"w":"exploit","p":"v.","d":"to use something or someone unfairly","c":"利用","s":"Companies should not exploit natural resources irresponsibly.","t":"公司不應該不負責任地利用自然資源。"},{"w":"exploited","p":"adj.","d":"used unfairly","c":"被利用的","s":"The exploited laborers were paid very little for their work.","t":"被利用的勞動者的工資很低。"}]},{"unit":4,"theme":"exploiter – inspector","cards":[{"w":"exploiter","p":"n.","d":"a person who uses others unfairly","c":"剝削者","s":"The exploiter was eventually brought to justice for his actions.","t":"剝削者最終因其行為被繩之以法。"},{"w":"exploitation","p":"n.","d":"unfair use of people or things","c":"剝削","s":"The film exposes the exploitation of workers in certain industries.","t":"電影揭示了某些行業中工人的剝削。"},{"w":"fluctuate","p":"v.","d":"to go up and down","c":"波動","s":"Stock prices tend to fluctuate based on market conditions.","t":"股票價格傾向於根據市場條件波動。"},{"w":"fluctuated","p":"adj.","d":"went up and down","c":"波動的","s":"The fluctuated income made budgeting a challenge.","t":"波動的收入使預算成為一個挑戰。"},{"w":"fluctuation","p":"n.","d":"a change up and down","c":"波動","s":"The fluctuation in the exchange rate can impact international business transactions.","t":"匯率的波動可能會影響國際商業交易。"},{"w":"guide","p":"v.","d":"to show someone the way","c":"引導","s":"The mentor will guide the new employees through the training program.","t":"導師將引導新員工完成培訓課程。"},{"w":"guide","p":"n.","d":"a book that gives information","c":"指南","s":"Please refer to the user guide for troubleshooting steps.","t":"請參考用戶指南以獲取疑難解答步驟。"},{"w":"guidance","p":"n.","d":"help and advice","c":"指導","s":"With proper guidance, they were able to complete the project on time.","t":"在適當的指導下，他們能夠按時完成項目。"},{"w":"guidelines","p":"n.","d":"rules or advice on how to do something","c":"指南","s":"The company has set strict guidelines for employee conduct.","t":"公司為員工行為制定了嚴格的指南。"},{"w":"highlight","p":"v.","d":"to show that something is important","c":"強調","s":"The report will highlight the major accomplishments of the team.","t":"報告將強調團隊的主要成就。"},{"w":"highlight","p":"n.","d":"the best or most important part","c":"重點","s":"One of the highlight of the event was the keynote speech.","t":"活動的重點之一是主題演講。"},{"w":"highlighted","p":"adj.","d":"marked to show importance","c":"被強調的","s":"The highlighted issues require immediate attention.","t":"被強調的問題需要立即關注。"},{"w":"implicit","p":"adj.","d":"suggested but not said directly","c":"含蓄的","s":"The implicit meaning of the poem is hard to grasp.","t":"詩的含蓄意義很難把握。"},{"w":"explicit","p":"adj.","d":"very clear and direct","c":"明確的","s":"The instructions were explicit and easy to follow.","t":"指令很明確，容易遵循。"},{"w":"induce","p":"v.","d":"to cause something to happen","c":"引起","s":"The medication can induce sleep in some patients.","t":"這種藥物可能會在一些病人中引起睡眠。"},{"w":"induced","p":"adj.","d":"caused by something","c":"誘導的","s":"The induced coma was necessary to reduce the swelling in his brain.","t":"誘導的昏迷是必要的，以減少他的大腦腫脹。"},{"w":"inevitable","p":"adj.","d":"certain to happen","c":"不可避免的","s":"The changes were inevitable given the circumstances.","t":"鑑於情況，變化是不可避免的。"},{"w":"inevitably","p":"adv.","d":"as was certain to happen","c":"不可避免地","s":"The project will inevitably face challenges as it progresses.","t":"隨著項目的進展，它將不可避免地面臨挑戰。"},{"w":"infrastructure","p":"n.","d":"basic systems like roads and power","c":"基礎設施","s":"The city needs to invest in its infrastructure to support growth.","t":"該市需要投資於其基礎設施以支持增長。"},{"w":"inspect","p":"v.","d":"to look at something carefully","c":"檢查","s":"The officer will inspect the premises for any safety violations.","t":"官員將檢查房屋是否存在任何安全違規行為。"},{"w":"inspector","p":"n.","d":"a person whose job is to inspect things","c":"檢查員","s":"The inspector identified several issues during the audit.","t":"檢查員在審計期間確定了幾個問題。"}]},{"unit":5,"theme":"inspected – predominantly","cards":[{"w":"inspected","p":"adj.","d":"checked carefully","c":"被檢查的","s":"The inspected equipment was found to be in good working condition.","t":"經檢查的設備處於良好的工作狀態。"},{"w":"inspection","p":"n.","d":"a careful check","c":"檢查","s":"The inspection revealed some discrepancies that needed to be addressed.","t":"檢查揭示了一些需要解決的差異。"},{"w":"intensity","p":"n.","d":"how strong something is","c":"強度","s":"The intensity of the storm caused widespread damage.","t":"暴風雨的強度造成了廣泛的損害。"},{"w":"intensify","p":"v.","d":"to become stronger","c":"加劇","s":"The conflict began to intensify as more countries got involved.","t":"隨著更多國家的參與，衝突開始加劇。"},{"w":"manipulate","p":"v.","d":"to control someone or something unfairly","c":"操縱","s":"It's unethical to manipulate people for personal gain.","t":"為了個人利益操縱他人是不道德的。"},{"w":"manipulative","p":"adj.","d":"good at controlling people unfairly","c":"操縱的","s":"He was a manipulative individual, always trying to control others.","t":"他是一個操縱型的個人，總是試圖控制他人。"},{"w":"manipulation","p":"n.","d":"controlling people or things unfairly","c":"操縱","s":"The manipulation of data can lead to incorrect conclusions.","t":"數據操縱可能導致不正確的結論。"},{"w":"minimum","p":"adj./n.","d":"the smallest amount possible","c":"最低的/最小值","s":"The minimum requirement for this job is a Bachelor's degree.","t":"這份工作的最低要求是學士學位。"},{"w":"minimised","p":"adj.","d":"made as small as possible","c":"最小化的","s":"The risks have been minimised through careful planning.","t":"通過仔細規劃，風險已被最小化。"},{"w":"nuclear power plant","p":"n.","d":"a place that makes electricity from nuclear energy","c":"核電廠","s":"The nuclear power plant is being inspected for safety compliance.","t":"核電廠正在接受安全合規檢查。"},{"w":"offset","p":"n.","d":"something that balances another thing","c":"抵消","s":"The gains in the stock market were offset by losses in the bond market.","t":"股市的收益被債券市場的損失所抵消。"},{"w":"offset","p":"v.","d":"to balance one thing with another","c":"抵消","s":"We can offset the carbon emissions by planting more trees.","t":"我們可以通過種植更多樹木來抵消碳排放。"},{"w":"paragraph","p":"n.","d":"a group of sentences about one idea","c":"段落","s":"Each paragraph in the essay should support your thesis statement.","t":"論文中的每一段都應支持你的論文陳述。"},{"w":"plus","p":"conj./prep./n.","d":"added to; and also","c":"加上/正的","s":"The cost of materials, plus the cost of labor, gives the total cost.","t":"材料成本加上勞動成本，得出總成本。"},{"w":"practice","p":"v.","d":"to do something again to get better","c":"練習","s":"To become proficient, you must practice daily.","t":"要熟練，你必須每天練習。"},{"w":"practice the law/medicine","p":"phr.","d":"to work as a lawyer or doctor","c":"從事法律/醫學","s":"She decided to practice law after graduating from university.","t":"她決定在大學畢業後從事法律工作。"},{"w":"practitioner","p":"n.","d":"a person who works in a skilled job","c":"從業者","s":"A medical practitioner should have a good understanding of human anatomy.","t":"醫學從業者應對人體解剖學有很好的理解。"},{"w":"dominate","p":"v.","d":"to have power or control over others","c":"主導","s":"One company seems to dominate the market in this sector.","t":"一家公司似乎主導了這個領域的市場。"},{"w":"dominant","p":"adj.","d":"most important or powerful","c":"主導的","s":"Their dominant position in the industry is due to their innovative products.","t":"他們在行業中的主導地位歸功於他們的創新產品。"},{"w":"domination","p":"n.","d":"power or control over others","c":"主導","s":"The domination of the market by a single entity is unhealthy for competition.","t":"市場由單一實體主導對競爭是不利的。"},{"w":"predominantly","p":"adv.","d":"mostly; mainly","c":"主要地","s":"The population in this area is predominantly elderly.","t":"這個地區的人口主要是老年人。"}]},{"unit":6,"theme":"prospect – intensive","cards":[{"w":"prospect","p":"n.","d":"the chance that something will happen","c":"前景","s":"The prospect of economic growth is promising.","t":"經濟增長的前景很有希望。"},{"w":"prospective","p":"adj.","d":"expected to be or happen in the future","c":"預期的","s":"The prospective buyers were shown around the property.","t":"預期的買家被帶到了物業周圍。"},{"w":"radical","p":"adj./n.","d":"very new and different; a person with extreme ideas","c":"激進的/根本的","s":"The group is known for its radical views on political reform.","t":"該組織以其對政治改革的激進觀點而聞名。"},{"w":"random","p":"adj.","d":"chosen by chance","c":"隨機的","s":"The survey included a random sample of the population.","t":"調查包括了人口的隨機樣本。"},{"w":"at random","p":"adv.","d":"by chance","c":"隨機地","s":"The prizes will be distributed at random to the attendees.","t":"獎品將隨機分發給與會者。"},{"w":"reinforce","p":"v.","d":"to make something stronger","c":"加強","s":"The training program was designed to reinforce the skills they had learned.","t":"訓練計劃旨在加強他們所學的技能。"},{"w":"reinforced","p":"adj.","d":"made stronger","c":"加強的","s":"The reinforced concrete can withstand higher pressures.","t":"加固混凝土可以承受更高的壓力。"},{"w":"reinforcement","p":"n.","d":"something that makes something stronger","c":"加固","s":"The building required reinforcement to remain structurally sound.","t":"建築物需要加固以保持結構完好。"},{"w":"restore","p":"v.","d":"to bring something back to its old condition","c":"恢復","s":"Efforts are underway to restore the damaged artwork.","t":"正在努力恢復受損的藝術品。"},{"w":"restored","p":"adj.","d":"brought back to good condition","c":"恢復的","s":"The restored building is now a popular tourist attraction.","t":"恢復的建築物現在是受歡迎的旅遊景點。"},{"w":"restoration","p":"n.","d":"bringing something back to good condition","c":"恢復","s":"The restoration of the ancient ruins took over a decade.","t":"古代遺址的恢復花了十多年的時間。"},{"w":"revise","p":"v.","d":"to change and improve something","c":"修訂","s":"The author had to revise the manuscript several times before publication.","t":"作者在出版前必須多次修訂手稿。"},{"w":"revised","p":"adj.","d":"changed and improved","c":"修訂的","s":"The revised edition of the textbook includes updated information.","t":"修訂版的教科書包含了更新的信息。"},{"w":"revision","p":"n.","d":"a change made to improve something","c":"修訂","s":"The revision process can be time-consuming, but it is crucial for quality assurance.","t":"修訂過程可能很耗時，但對於保證質量至關重要。"},{"w":"schedule","p":"v.","d":"to plan a time for something","c":"排程","s":"They had to schedule a new meeting after the cancellation.","t":"他們不得不在取消後安排新的會議。"},{"w":"schedule","p":"n.","d":"a plan of times for events","c":"日程","s":"According to the schedule, the conference will start at 9 AM.","t":"根據日程，會議將於上午9點開始。"},{"w":"on schedule","p":"phr.","d":"at the planned time","c":"按計劃","s":"The project was completed on schedule despite numerous challenges.","t":"儘管面臨無數挑戰，該項目仍按計劃完成。"},{"w":"tense","p":"adj.","d":"nervous and worried","c":"緊張的","s":"The atmosphere in the room was tense as everyone awaited the announcement.","t":"隨著每個人都在等待宣布，房間裡的氣氛變得緊張。"},{"w":"tension","p":"n.","d":"a feeling of worry or stress","c":"緊張","s":"The tension between the two groups was palpable.","t":"兩組之間的緊張是明顯的。"},{"w":"intense","p":"adj.","d":"very strong","c":"強烈的","s":"The intense heat made it difficult to work outdoors.","t":"強烈的熱使得在戶外工作變得困難。"},{"w":"intensive","p":"adj.","d":"done with a lot of effort in a short time","c":"密集的","s":"The intensive course covers a lot of material in a short period of time.","t":"密集課程在短時間內涵蓋了大量材料。"}]},{"unit":7,"theme":"intensify – visual","cards":[{"w":"intensify","p":"v.","d":"to become stronger","c":"加劇","s":"The debate is likely to intensify as the election approaches.","t":"隨著選舉的臨近，辯論可能會加劇。"},{"w":"terminate","p":"v.","d":"to end something","c":"終止","s":"They had no choice but to terminate the contract early.","t":"他們別無選擇，只能提前終止合同。"},{"w":"terminated","p":"adj.","d":"ended","c":"被終止的","s":"The terminated agreement led to legal disputes between the parties.","t":"被終止的協議導致了雙方之間的法律糾紛。"},{"w":"termination","p":"n.","d":"the act of ending something","c":"終止","s":"The termination of employment can be a stressful event for anyone.","t":"解僱可能是任何人的壓力事件。"},{"w":"theme","p":"n.","d":"the main subject or idea","c":"主題","s":"The theme of the conference is sustainable development.","t":"會議的主題是可持續發展。"},{"w":"thereby","p":"adv.","d":"as a result of this","c":"從而","s":"By automating the process, they thereby increased efficiency.","t":"通過自動化過程，他們從而提高了效率。"},{"w":"uniform","p":"adj./n.","d":"the same; a special set of clothes","c":"統一的/制服","s":"All students are required to wear a uniform to school.","t":"所有學生都必須穿制服上學。"},{"w":"unify","p":"v.","d":"to join things together into one","c":"統一","s":"The new leader hopes to unify the country after years of division.","t":"新領導人希望在多年的分裂後統一這個國家。"},{"w":"unity","p":"n.","d":"being together as one","c":"統一","s":"The event aimed to promote unity and collaboration among different communities.","t":"這個活動旨在促進不同社區之間的統一和合作。"},{"w":"vehicle","p":"n.","d":"a car, bus or truck","c":"車輛","s":"The vehicle was towed away due to illegal parking.","t":"由於非法停車，車輛被拖走了。"},{"w":"via","p":"prep.","d":"by way of; through","c":"通過","s":"You can reach the support team via email or phone.","t":"你可以通過電子郵件或電話聯絡支持團隊。"},{"w":"virtue","p":"n.","d":"a good quality in a person","c":"美德","s":"Patience is a virtue that he certainly lacks.","t":"耐心是他肯定缺乏的美德。"},{"w":"virtual","p":"adj.","d":"existing on a computer, not in real life","c":"虛擬的","s":"The virtual reality experience was incredibly realistic.","t":"虛擬現實體驗非常逼真。"},{"w":"virtually","p":"adv.","d":"almost completely","c":"實際上","s":"The small town is virtually unknown to the outside world.","t":"這個小鎮實際上是外界所不知道的。"},{"w":"widespread","p":"adj.","d":"found in many places","c":"廣泛的","s":"There's widespread agreement among experts about the cause of the issue.","t":"專家們對問題的原因有廣泛的一致看法。"},{"w":"visual","p":"adj.","d":"about seeing","c":"視覺的","s":"The visual effects in the movie were stunning.","t":"電影中的視覺效果令人驚嘆。"}]}];
